using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1 – Discriminator property renamed "$type" (was "Discriminator").
        // Keep the old name so existing documents are still recognised.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2 – Resource id no longer prefixed with discriminator.
        // EF8 synthesised id = "Blog|<key>"; EF9 uses just "<key>".
        // Keep the legacy "Blog|<key>" format for existing documents.
        modelBuilder.Entity<Blog>()
            .Property("__id")                       // the shadow property EF maps to JSON "id"
            .HasValueGeneratorFactory<LegacyBlogIdGeneratorFactory>();

        // Breaking change 3 – HasIndex() now throws for the Cosmos provider.
        // Cosmos manages indexes via its server-side indexing policy — call removed.
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

/// <summary>
/// Reproduces the EF Core 8 id format: "Blog|{key}"
/// </summary>
class LegacyBlogIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Blog|{entry.Property("Id").CurrentValue}";
}

class LegacyBlogIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(IProperty property, IEntityType entityType)
        => new LegacyBlogIdGenerator();
}

